functions.shortcutKey:
function shortcutKey(){ 		
    	$(document).bind('keydown', function(e) {
    		var keyCode = (e.keyCode) ? e.keyCode : ((e.charCode) ? e.charCode : e.which);
    		if (e.originalEvent.altKey) {
    			// ALT + S     Search                   
    			if (keyCode === 83) {
    				reloadSearchGrid();
    				e.preventDefault();
    				return false;

    			}
    			// ALT + N      Reset                 
    			if (keyCode == 78) {
    				resetAll();
    				e.preventDefault();
    				return false;
    			}
    			// ALT + F    Add New
    			if (keyCode == 70){
    				addnew();
    				e.preventDefault();
    				return false;
    			}

    		}
    	});
    }

functions.openRequestResponseBody:
function openRequestResponseBody(event, id){
			if(id != undefined && id != null && id != "") {

				var retVal = $.ajax({
					url : "fetchRequestResponseById",

					type : "POST",
					data : {
						transId : id
					},
					dataType : "json",
					async : false
				}).responseText;

				retVal = jQuery.parseJSON(retVal);
				if(retVal != null && retVal != undefined && retVal.transmitLogDTO != null 
						&& (retVal.transmitLogDTO.requestJson != null || retVal.transmitLogDTO.responseJson != null)){//VE-31975 SE
					//VE-16029 S
					try {
						if(retVal.transmitLogDTO.requestJson != undefined && retVal.transmitLogDTO.requestJson != "")
							editor.setValue(JSON.stringify(JSON.parse(retVal.transmitLogDTO.requestJson), null, '\t'), -1);
						else
							editor.setValue("");
					} catch (e) {
						if(retVal.transmitLogDTO.requestJson != undefined && retVal.transmitLogDTO.requestJson != "")
							editor.setValue(retVal.transmitLogDTO.requestJson);
						else
							editor.setValue("");						
					}
					try {
						if(retVal.transmitLogDTO.responseJson != undefined && retVal.transmitLogDTO.responseJson != "")
							editor1.setValue(JSON.stringify(JSON.parse(retVal.transmitLogDTO.responseJson), null, '\t'), -1);
						else
							editor1.setValue("");
					} catch(e) {
						if(retVal.transmitLogDTO.responseJson != undefined && retVal.transmitLogDTO.responseJson != "")
							editor1.setValue(retVal.transmitLogDTO.responseJson);
						else
							editor1.setValue("");
					}
					var rowData = jQuery("#taxSettingLogTable").getRowData(id);
					let str = "";
					if(rowData != undefined && rowData != null && rowData != ""){

						str = "Document Number";
						str += " : " + rowData.documentNo + " [ Exec Time : " + rowData.execTime + "s ]";
					}
					$("#headLabel").html(str);
					//VE-16029 E
					$("#requestResponseDialog").modal("show");
				}
				else{
					window.parent.showAlert('Something Went Wrong');
					return false;
				}
			}
		}

functions.openOrderLink:
function openOrderLink(orderNo, orderType,refrenceNo, event){
			var clientId = $("#gs_clientId").val() != null && $("#gs_clientId").val() != ''  ? $("#gs_clientId").val() :"0";
			if (window.parent){
				if(orderType == "STO")
					window.parent.openScreen("STO Order Create/Edit","stockOrderMaintDisplayBS?stkTransferCode=" + orderNo, "fa fa-fw fa-list-ol");

				else if(orderType.toUpperCase() == "RETURN"){
					if(refrenceNo != "")
					window.parent.openScreen("Return Create/Edit-"+orderNo,"custReturnFetchDataBS?custRetCode="+ orderNo+"&clientIds=" +clientId, "fa fa-fw fa-list-ol");  
					else
						window.parent.openScreen("Return W/o Order  - "+orderNo,"custRetWithOutDisplay?custRetCode="+ orderNo, "fa fa-fw fa-list-ol");
				}
				else if(orderType == "RTV")
					window.parent.openScreen("Vendor Return Create/Edit","vendorReturnsFetchDataBS?rtvNo="+ orderNo, "fa fa-fw fa-list-ol");
				else
					window.parent.openScreen("Order Create/Edit - "+orderNo, "orderMaintenanceBS?orderCode="+orderNo, "fa fa-fw fa-simplybuilt");

			  return false;
			}
		 }

